      tests: [{"name": "A hall call brings the car", "steps": ["tap I1.6", "expect Q3.6=1", "waitfor I2.3=1 I3.4=1 15000", "expect Q3.6=0", "plant s3=1"]}, {"name": "Going up it stops for UP calls only, the DOWN call later", "steps": ["tap I0.4", "tap I1.2", "tap I1.5", "waitfor I2.2=1 I3.4=1 10000", "expect Q3.2=0 Q3.5=1 Q1.0=1", "waitfor I2.4=1 I3.4=1 20000", "expect Q1.1=1 Q1.0=0", "waitfor I2.2=1 I3.4=1 25000", "expect Q3.5=0", "plant s2=2 s4=1 s1=0 s3=0"]}, {"name": "Passes a DOWN call while travelling up to a higher call", "steps": ["tap I0.4", "tap I1.5", "waitfor I2.4=1 I3.4=1 20000", "plant s2=0", "waitfor I2.2=1 I3.4=1 20000", "plant s2=1"]}, {"name": "Lanterns show the direction", "steps": ["tap I0.3", "wait 500", "expect Q1.0=1 Q1.1=0"]}, {"name": "Keeps its direction: up calls first, then down", "steps": ["tap I0.3", "waitfor MW20=1 6000", "tap I0.0", "tap I0.4", "waitfor I2.3=1 I3.4=1 12000", "waitfor I2.4=1 I3.4=1 15000", "waitfor I2.0=1 I3.4=1 30000", "plant s0=1 s3=1 s4=1 s1=0 s2=0"]}],
